// Production HMAC-SHA256 signature and replay attack verification
const crypto = require('crypto');
const secret = $env.WEBHOOK_SECRET || 'lendloop-shared-hmac-secret-key-prod';

const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);

const signature = headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'];
const timestamp = headers['x-lendloop-timestamp'] || headers['X-LendLoop-Timestamp'];
const nonce = headers['x-lendloop-nonce'] || headers['X-LendLoop-Nonce'];

if (!signature || !timestamp || !nonce) {
  throw new Error('Unauthorized: Missing HMAC security headers');
}

// 5-minute replay window check
const now = Date.now();
const reqTime = parseInt(timestamp, 10);
if (isNaN(reqTime) || Math.abs(now - reqTime) > 300000) {
  throw new Error(`Unauthorized: Timestamp outside acceptable window (drift: ${Math.round(Math.abs(now - reqTime)/1000)}s)`);
}

// Verify HMAC
const message = `${timestamp}:${nonce}:${rawBody}`;
const expectedSignature = crypto.createHmac('sha256', secret).update(message).digest('hex');
const cleanSig = signature.replace(/^sha256=/, '');

if (cleanSig !== expectedSignature) {
  throw new Error('Unauthorized: Invalid HMAC signature');
}

const payload = typeof body === 'string' ? JSON.parse(body) : body;
return [{ json: payload }];

const data = $input.first().json;
const message = `[LendLoop Alert] Hi ${data.lenderName}, neighbor ${data.borrowerName} requested to borrow '${data.toolName}' from ${data.startDate} to ${data.endDate}. Please sign in to approve or decline.`;
console.log(`[Notification Dispatched to ${data.recipientEmail}]:`, message);
return [{ json: { recipient: data.recipientEmail, message, status: 'dispatched', event: 'loan_requested', loanId: data.loanId } }];

